//docs.rs/ruststream-kinesis/0.7/ruststream_kinesis/struct.DynamoLeaseStore.html",children:(0,r.jsx)(n.code,{children:"DynamoLeaseStore"})})," keeps leases in a DynamoDB table, so several instances share the shards; the table needs only a string key ",(0,r.jsx)(n.code,{children:"lease_key"}),"."]}),"\n",(0,r.jsxs)(n.p,{children:["It needs the ",(0,r.jsx)(n.code,{children:"dynamodb-lease"})," feature of the crate.\n",(0,r.jsx)(n.a,{href:"https://docs.rs/ruststream-kinesis/0.7/ruststream_kinesis/struct.DynamoLeaseStore.html#method.new",children:(0,r.jsx)(n.code,{children:"DynamoLeaseStore::new"})})," takes the AWS configuration and the table name.\nThe table has a string partition key named ",(0,r.jsx)(n.code,{children:"lease_key"})," and nothing else; on-demand billing fits it.\nOne row holds one shard of one stream, under the key ",(0,r.jsx)(n.code,{children:"stream:shard"}),", so one table serves every stream of a service.\nThe row holds the owner, the lease's expiry, the checkpoint and a counter bumped on every write.\nEvery write is conditional, so two instances never both hold a shard, and a checkpoint lands only while its writer holds the lease.\nThe checkpoints outlive the process, so a restarted instance resumes each shard where its acknowledgements stopped.\nThe broker is built from the same configuration with ",(0,r.jsx)(n.a,{href:"https://docs.rs/ruststream-kinesis/0.7/ruststream_kinesis/struct.KinesisBroker.html#method.from_config",children:(0,r.jsx)(n.code,{children:"KinesisBroker::from_config"})}),", so both reach one account and region.\nThe service's credentials need ",(0,r.jsx)(n.code,{children:"dynamodb:GetItem"})," and ",(0,r.jsx)(n.code,{children:"dynamodb:UpdateItem"})," on the table.\nEach instance needs an ",(0,r.jsx)(n.a,{href:"/ruststream-kinesis/latest/ru/components/leases/owner-id",children:"owner id"})," of its own; a table written by an earlier version of this crate is read through ",(0,r.jsx)(n.a,{href:"/ruststream-kinesis/latest/ru/components/leases/legacy-stream",children:(0,r.jsx)(n.code,{children:"legacy_stream"})}),"."]}),"\n",(0,r.jsx)(n.h2,{id:"example",children:"Example"}),"\n",(0,r.jsx)(n.p,{children:"Every instance of the fulfilment service runs this code against one table."}),"\n",(0,r.jsxs)(o.A,{groupId:"api",children:[(0,r.jsx)(i.A,{value:"macros",label:"Macros",children:(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream-kinesis/blob/main/crates/ruststream-kinesis/examples/kinesis_leases.rs"',children:'/// Fulfils each order. Every instance runs this handler, and each shard is read by the one\n/// instance that holds its lease in the table.\n#[subscriber(KinesisStream::new("fulfilment"))]\nasync fn fulfil(order: &Order) -> HandlerOutcome {\n    tracing::info!(order.id, "fulfilled");\n    HandlerOutcome::ack()\n}\n\n/// The lease store and the broker share one AWS configuration: one account, one region.\nfn broker(config: &SdkConfig, table: &str) -> KinesisBroker {\n    let leases = Arc::new(DynamoLeaseStore::new(config, table));\n    KinesisBroker::from_config(config.clone()).lease_store(leases)\n}\n\nfn service(broker: KinesisBroker) -> RustStream {\n    RustStream::new(AppInfo::new("fulfilment", "0.1.0")).with_broker(broker, |b| {\n        b.include(fulfil);\n    })\n}\n'})})}),(0,r.jsx)(i.A,{value:"manual",label:"Manual",children:(0,r.jsx)(n.pre,{children:(0,r.jsx)(n.code,{className:"language-rust",metastring:'title="https://github.com/powersemmi/ruststream-kinesis/blob/main/crates/ruststream-kinesis/examples/manual/kinesis_leases.rs"',children:'/// Fulfils each order. Every instance runs this handler, and each shard is read by the one\n/// instance that holds its lease in the table.\nstruct Fulfil;\n\nimpl Handle<Order> for Fulfil {\n    fn handle(\n        &self,\n        order: &Order,\n        _outs: &(),\n        _ctx: &mut Context<\'_>,\n    ) -> impl Future<Output = Result<(), HandlerOutcome>> {\n        tracing::info!(order.id, "fulfilled");\n        ready(Ok(()))\n    }\n}\n\n/// The lease store and the broker share one AWS configuration: one account, one region.\nfn broker(config: &SdkConfig, table: &str) -> KinesisBroker {\n    let leases = Arc::new(DynamoLeaseStore::new(config, table));\n    KinesisBroker::from_config(config.clone()).lease_store(leases)\n}\n\nfn service(broker: KinesisBroker) -> RustStream {\n    RustStream::new(AppInfo::new("fulfilment", "0.1.0")).with_broker(broker, |b| {\n        b.include(subscriber(KinesisStream::new("fulfilment"), Fulfil).build());\n    })\n}\n'})})})]})]})}function m(e={}){let{wrapper:n}={...(0,a.R)(),...e.components};return n?(0,r.jsx)(n,{...e,children:(0,r.jsx)(h,{...e})}):h(e)}},7250(e,n,s){s.d(n,{A:()=>i});var t=s(4848);s(6540);var r=s(4164),a=s(7663);function o({children:e,className:n,hidden:s}){return(0,t.jsx)("div",{role:"tabpanel",className:(0,r.A)("tabItem_Ymn6",n),hidden:s,children:e})}function i({children:e,className:n,value:s}){let{selectedValue:r,lazy:l}=(0,a.uc)(),c=s===r;return!c&&l?null:(0,t.jsx)(o,{className:n,hidden:!c,children:e})}},773(e,n,s){s.d(n,{A:()=>h});var t=s(4848);s(6540);var r=s(4164),a=s(8287),o=s(7663),i=s(8584),l=s(9863);function c({className:e}){let{selectedValue:n,selectValue:s,tabValues:a,block:l}=(0,o.uc)(),u=[],{blockElementScrollPositionUntilNextRender:d}=(0,i.a_)(),h=e=>{let t=e.currentTarget,r=a[u.indexOf(t)].value;r!==n&&(d(t),s(r))},m=e=>{let n=null;switch(e.key){case"Enter":h(e);break;case"ArrowRight":{let s=u.indexOf(e.currentTarget)+1;n=u[s]??u[0];break}case"ArrowLeft":{let s=u.indexOf(e.currentTarget)-1;n=u[s]??u[u.length-1]}}n?.focus()};return(0,t.jsx)("ul",{role:"tablist","aria-orientation":"horizontal",className:(0,r.A)("tabs",{"tabs--block":l},e),children:a.map(({value:e,label:s,attributes:a})=>(0,t.jsx)("li",{role:"tab",tabIndex:n===e?0:-1,"aria-selected":n===e,ref:e=>{u.push(e)},onKeyDown:m,onClick:h,...a,className:(0,r.A)("tabs__item","tabItem_LNqP",a?.classNam